/// Rule F2: the session context file is rewritten from the fold before anything reads it.
fn write_session_context(&self, session: &SessionId) -> Result<(), EngineError> {
    let st = self.snapshot(session)?;
    let path = st.session_context_path();
    std::fs::write(&path, crate::context::render(&st)).map_err(|e| {
        EngineError::Invalid(format!("Could not write {}: {e}", path.display()))
    })
}

let docs = s.research_docs();
if !docs.is_empty() {
    let _ = writeln!(m, "## Research documents\n");
    for d in docs {
        let _ = writeln!(m, "- `{}`", d.display());
    }
    m.push('\n');
}
if let Some(spec) = &s.spec.current {
    let _ = writeln!(
        m,
        "## Spec\n\n- `{}`: {} (approved: {})\n",
        spec.spec_path, spec.summary, s.spec.approved
    );
}

fn apply_classify(&mut self, out: &ClassifyOut) {
    self.category = Some(out.category);
    if let Some(t) = clean_title(&out.title) {
        self.title = Some(t);
    }

if let Some(r) = &p.revision {
    // Rule F2: a revision reads the session context file, not a conversation.
    inputs.revision = Some(r.round);
    inputs.task = Some(revision_task(r, &s.full_request()));
    inputs.context_files = vec![s.session_context_path()];
    inputs.prior_reports = s
        .phases
        .values()
        .filter(|q| q.info.project == project && q.info.id != phase)
        .filter_map(|q| q.implementer_report.clone())
        .collect();
}
